const mongoose = require('mongoose');

const bookingSchema = new mongoose.Schema({
  itemId: {
    type: mongoose.Types.ObjectId,
    ref: 'Item'
  },
  borrowerId: {
    type: mongoose.Types.ObjectId,
    ref: 'User'
  },
  startDate: {
    type: Date
  },
  endDate: {
    type: Date
  }
});

module.exports = mongoose.model('Booking', bookingSchema);

const Item = require('../models/Item');

exports.createItem = async (req, res) => {
  try {
    const { title, description, pricePerDay, isFree } = req.body;
    if (!title || !description || typeof pricePerDay !== 'number' || typeof isFree !== 'boolean') {
      return res.status(400).json({ error: 'Invalid data provided.' });
    }

    const newItem = new Item({
      ownerId: req.user._id,
      title,
      description,
      pricePerDay,
      isFree
    });

    await newItem.save();
    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create item.' });
  }
};

const Booking = require('../models/Booking');
const Item = require('../models/Item');

exports.requestBooking = async (req, res) => {
  try {
    const { itemId, startDate, endDate } = req.body;
    if (!itemId || !startDate || !endDate) {
      return res.status(400).json({ error: 'Invalid data provided.' });
    }

    const item = await Item.findById(itemId);
    if (!item) {
      return res.status(404).json({ error: 'Item not found.' });
    }

    if (item.ownerId.toString() === req.user._id.toString()) {
      return res.status(403).json({ error: 'Cannot book your own item.' });
    }

    const newBooking = new Booking({
      itemId,
      borrowerId: req.user._id,
      startDate,
      endDate
    });

    await newBooking.save();
    res.status(201).json(newBooking);
  } catch (error) {
    res.status(500).json({ error: 'Failed to request booking.' });
  }
};

